// src/init/retired-access-rules.ts
/** The column the stored rules lived in. */
const RETIRED_ACCESS_RULES_COLUMN = "access_rules";
/** The two registry tables that carried it. */
const RETIRED_ACCESS_RULES_TABLES = ["dynamic_collections", "dynamic_singles"];
/**
* Which registry tables in this database still carry the retired column.
*
* A NEW database never gets the column, and an old one that has run the drop
* no longer has it, so on those the answer is empty and nothing is counted.
* Judged on the live snapshot rather than assumed from the version, because
* the column's presence is the only thing that decides whether the count
* below can even be asked.
*/
function findRetiredAccessRulesColumns(live) {
	return live.tables.filter((table) => RETIRED_ACCESS_RULES_TABLES.includes(table.name) && table.columns.some((column) => column.name === "access_rules")).map((table) => table.name);
}
/**
* How many rows of each table still hold a rule.
*
* Derived as rows minus null rows rather than asked with its own predicate: the
* two counts already exist, and a third query written here would be a second
* place for a dialect's quoting or result shape to be wrong. A row with no
* rule was always stored as NULL, so "not null" is exactly "holds a rule".
*
* Tables with nothing to report are dropped here, so the caller warns only
* about what actually needs attention.
*/
async function countRetiredAccessRules(db, dialect, tables, deps) {
	return (await Promise.all(tables.map(async (table) => {
		const [total, empty] = await Promise.all([deps.countRows(db, dialect, table), deps.countNulls(db, dialect, table, RETIRED_ACCESS_RULES_COLUMN)]);
		return {
			table,
			rows: total - empty
		};
	}))).filter((entry) => entry.rows > 0);
}
function formatRetiredAccessRulesWarning(found) {
	return [
		"[nextly] Your database still holds stored access rules, and this version of Nextly no longer enforces them.",
		"",
		...found.map((entry) => `  ${entry.table}: ${entry.rows} ${entry.rows === 1 ? "row carries" : "rows carry"} a value in \`${RETIRED_ACCESS_RULES_COLUMN}\``),
		"",
		"  Access is now decided by the RBAC gate alone: a super-admin session bypasses it; otherwise a",
		"  caller needs the role permission for the operation, granted in the database, and the",
		"  code-defined `access` on the collection's or Single's config, where it names the operation,",
		"  only narrows that permission. Existing role grants still apply; only the rules in this column",
		"  are ignored. Review those rules, express any you still need as code-defined `access` beside",
		"  the role permission it narrows, then remove the column:",
		"  `nextly migrate` will name it and refuse, and NEXTLY_ALLOW_CORE_DESTRUCTIVE=1 drops it."
	].join("\n");
}
export { RETIRED_ACCESS_RULES_COLUMN, RETIRED_ACCESS_RULES_TABLES, countRetiredAccessRules, findRetiredAccessRulesColumns, formatRetiredAccessRulesWarning };
